  --popover: #ffffff;
  --popover-foreground: #1b1e2b;
  --primary: #d8891a;
  --primary-foreground: #241a05;
  --secondary: #eef0f6;
  --secondary-foreground: #1b1e2b;
  --muted: #eef0f6;
  --muted-foreground: #5b6072;
  --accent: #eef0f6;
  --accent-foreground: #1b1e2b;
  --destructive: #e5484d;
  --destructive-foreground: #0e1018;
  --border: #e4e7ef;
  --input: #e4e7ef;
  --ring: #9a5c08;
