  --accent: #1e2231;
  --accent-foreground: #eceef6;
  --destructive: #f2585d;
  --destructive-foreground: #1b1e2b;
  --border: #272b3b;
  --input: #272b3b;
  --ring: #f5b843;
  --sidebar: #10121c;
